record.field:
from markupsafe import Markup

fields_data = dict(params.get('fields') or {})

# Resolve execution user
if room and room.assigned_to_id and not room.assigned_to_id.share:
    exec_user = room.assigned_to_id
else:
    exec_user = env.ref('base.user_admin')

lead_model = env['crm.lead'].sudo().with_user(exec_user)

# Auto-resolve phone from Evolution/WhatsApp channel metadata when not provided
if not fields_data.get('phone') and room and room.connector_id:
    connector_type = (room.connector_id.connector_type or '').lower()
    ext_id = room.external_id or ''
    if connector_type == 'evolution' and ext_id and '@' not in ext_id:
        digits = ''.join(c for c in ext_id if c.isdigit() or c == '+')
        if sum(1 for c in digits if c.isdigit()) >= 8:
            fields_data['phone'] = digits

# Strip auto-managed fields so the AI cannot override them
for protected in ('id', 'chatroom_room_ids', 'type', 'user_id', 'partner_id'):
    fields_data.pop(protected, None)

# Check for an existing lead already linked to this room
existing = None
room_id = room.id if room else False
if room_id and 'chatroom_room_ids' in env['crm.lead']._fields:
    existing = lead_model.search(
        [('chatroom_room_ids', 'in', [room_id])], limit=1, order='id desc'
    )

if existing:
    # Update: only fill in fields that are currently empty on the lead
    update_vals = {}
    for fname, fval in fields_data.items():
        if fval in (None, '', False):
            continue
        if fname not in existing._fields:
            continue
        current = existing[fname]
        # For numeric fields, 0 is a valid existing value — don't overwrite
        if current is False or current is None or current == '':
            update_vals[fname] = fval
    if update_vals:
        existing.write(update_vals)
    lead = existing
    action = 'updated'
else:
    # Create: build write_vals from AI-provided fields plus auto-resolved values
    crm_use_lead = env.user.has_group('crm.group_use_lead')
    write_vals = {k: v for k, v in fields_data.items() if v not in (None, '', False)}
    write_vals.setdefault('name', room.name if room else 'Lead from chat')
    write_vals['type'] = 'lead' if crm_use_lead else 'opportunity'
    if room and room.partner_ids:
        write_vals.setdefault('partner_id', room.partner_ids[0].id)
    if room and room.assigned_to_id and not room.assigned_to_id.share:
        write_vals.setdefault('user_id', room.assigned_to_id.id)
    if room_id and 'chatroom_room_ids' in env['crm.lead']._fields:
        write_vals['chatroom_room_ids'] = [(4, room_id)]
    lead = lead_model.create(write_vals)
    action = 'created'

# Post a chatter note linking back to the chat
chat_url = f'/web#action=chatroom.action_chatroom_app&room_id={room_id}'
agent_name = agent.name if agent else 'AI Agent'
lead.with_user(exec_user).message_post(
    body=Markup(
        f'<p>Lead {action} by AI agent <strong>{agent_name}</strong>.</p>'
        f'<p><a href="{chat_url}" target="_blank">View source chat</a></p>'
    ),
    message_type='comment',
    subtype_xmlid='mail.mt_note',
)

result = {'success': True, 'lead_id': lead.id, 'action': action}

from markupsafe import Markup

fields_data = dict(params.get('fields') or {})
lead_id_param = params.get('lead_id')

# Resolve execution user
if room and room.assigned_to_id and not room.assigned_to_id.share:
    exec_user = room.assigned_to_id
else:
    exec_user = env.ref('base.user_admin')

lead_model = env['crm.lead'].sudo().with_user(exec_user)
room_id = room.id if room else False

# Resolve lead: by explicit ID first, then by room link
lead = None
if lead_id_param:
    lead = lead_model.browse(int(lead_id_param)).exists() or None
if not lead and room_id and 'chatroom_room_ids' in env['crm.lead']._fields:
    found = lead_model.search(
        [('chatroom_room_ids', 'in', [room_id])], limit=1, order='id desc'
    )
    lead = found or None

if not lead:
    result = {
        'success': False,
        'error': 'No lead found. Use save_lead first to create one for this conversation.',
    }
else:
    for protected in ('id', 'chatroom_room_ids', 'type'):
        fields_data.pop(protected, None)

    write_vals = {k: v for k, v in fields_data.items()
                  if v is not None and k in lead._fields}
    if write_vals:
        lead.write(write_vals)

    chat_url = f'/web#action=chatroom.action_chatroom_app&room_id={room_id}'
    agent_name = agent.name if agent else 'AI Agent'
    lead.with_user(exec_user).message_post(
        body=Markup(
            f'<p>Lead updated by AI agent <strong>{agent_name}</strong>.</p>'
            f'<p><a href="{chat_url}" target="_blank">View source chat</a></p>'
        ),
        message_type='comment',
        subtype_xmlid='mail.mt_note',
    )
    result = {'success': True, 'lead_id': lead.id, 'updated_fields': list(write_vals.keys())}
